let currentScreenIndex = 0;

/* Renderização da Navegação Lateral */
function renderSidebar() {
  const nav = document.getElementById("sidebarNav");
  nav.innerHTML = "";

  let currentStage = -1;
  let groupEl = null;

  SCREENS.forEach((screen, index) => {
    if (screen.stageNum !== currentStage) {
      currentStage = screen.stageNum;
      groupEl = document.createElement("div");
      groupEl.className = "stage-group";
      const titleEl = document.createElement("div");
      titleEl.className = "stage-title";
      titleEl.textContent = screen.stage;
      groupEl.appendChild(titleEl);
      nav.appendChild(groupEl);
    }

    const itemBtn = document.createElement("button");
    itemBtn.className = "stage-item" + (index === currentScreenIndex ? " active" : "");
    itemBtn.onclick = () => goToScreen(index);

    const topDiv = document.createElement("div");
    topDiv.className = "stage-item-top";

    const idSpan = document.createElement("span");
    idSpan.className = "stage-item-id";
    idSpan.textContent = screen.id;
    topDiv.appendChild(idSpan);

    if (screen.badges.includes("pico")) {
      const b = document.createElement("span");
      b.className = "badge-pill badge-pico";
      b.textContent = "PICO";
      topDiv.appendChild(b);
    } else if (screen.badges.includes("aha")) {
      const b = document.createElement("span");
      b.className = "badge-pill badge-aha";
      b.textContent = "AHA";
      topDiv.appendChild(b);
    } else if (screen.badges.includes("trava")) {
      const b = document.createElement("span");
      b.className = "badge-pill badge-trava";
      b.textContent = "TRAVA";
      topDiv.appendChild(b);
    } else if (screen.actor === "professor") {
      const b = document.createElement("span");
      b.className = "badge-pill badge-prof";
      b.textContent = "PROF";
      topDiv.appendChild(b);
    }

    const descDiv = document.createElement("div");
    descDiv.className = "stage-item-desc";
    descDiv.textContent = screen.title;

    itemBtn.appendChild(topDiv);
    itemBtn.appendChild(descDiv);
    groupEl.appendChild(itemBtn);
  });
}

/* Renderização da Tela Ativa */
function renderScreen() {
  const screen = SCREENS[currentScreenIndex];

  // Header superior
  document.getElementById("topScreenTitle").textContent = `${screen.id} · ${screen.title}`;
  document.getElementById("navCounter").textContent = `${currentScreenIndex + 1} / ${SCREENS.length}`;

  const topBadges = document.getElementById("topBadges");
  topBadges.innerHTML = "";
  if (screen.badges.includes("pico")) topBadges.innerHTML += '<span class="badge-pill badge-pico">PICO</span>';
  if (screen.badges.includes("aha")) topBadges.innerHTML += '<span class="badge-pill badge-aha">AHA / MEMORÁVEL</span>';
  if (screen.badges.includes("trava")) topBadges.innerHTML += '<span class="badge-pill badge-trava">TRAVA DOCENTE</span>';
  if (screen.actor === "professor") topBadges.innerHTML += '<span class="badge-pill badge-prof">PROFESSOR</span>';

  // Botões de navegação
  document.getElementById("btnPrev").disabled = currentScreenIndex === 0;
  document.getElementById("btnNext").disabled = currentScreenIndex === SCREENS.length - 1;

  // Palco
  const stage = document.getElementById("stageContainer");
  const infoTag = document.getElementById("viewportInfoTag");

  if (screen.isDesktop) {
    infoTag.textContent = "janela do hub, 1366×768 (visão do professor / telão)";
    stage.innerHTML = `
      <div class="desktop-frame">
        <div class="frame-inner">${screen.render()}</div>
        <div class="frame-footer-note">${screen.id} — ${screen.title}</div>
      </div>
    `;
  } else {
    infoTag.textContent = "casca de aparelho 375×812 dentro do hub (estudante individual)";
    stage.innerHTML = `
      <div class="phone-frame">
        <div class="frame-inner">${screen.render()}</div>
        <div class="frame-footer-note">${screen.id} — ${screen.title}</div>
      </div>
    `;
  }

  // Painel lateral
  const panelData = STAGE_PANELS[screen.stageNum] || STAGE_PANELS[0];
  document.getElementById("panelStageTag").textContent = panelData.tag;
  document.getElementById("panelStageName").textContent = panelData.name;
  document.getElementById("panelStageDesc").innerHTML = panelData.desc;
  document.getElementById("panelSourceDecl").textContent = "Fonte: " + panelData.source;

  // Rodapé
  document.getElementById("footScreenId").textContent = screen.id;
  document.getElementById("footScreenAction").textContent = screen.action;
  document.getElementById("footScreenNext").textContent = screen.next;

  renderSidebar();
}

function goToScreen(index) {
  if (index >= 0 && index < SCREENS.length) {
    currentScreenIndex = index;
    renderScreen();
  }
}

/* Interações Específicas Scriptadas */
function updateCharCount(val) {
  const len = val.length;
  const counterEl = document.getElementById("charCounter");
  const btn = document.getElementById("btnSalvarReflexao");

  if (len < 15) {
    counterEl.textContent = `Mínimo de 15 caracteres (faltam ${15 - len} caracteres)`;
    counterEl.style.color = "var(--texto-secundario)";
    btn.disabled = true;
    btn.style.opacity = "0.4";
    btn.style.cursor = "not-allowed";
  } else if (len <= 240) {
    counterEl.textContent = `${len} / 240 caracteres (Válido)`;
    counterEl.style.color = "var(--texto-primario)";
    btn.disabled = false;
    btn.style.opacity = "1";
    btn.style.cursor = "pointer";
  } else {
    counterEl.textContent = `Limite ultrapassado (${len}/240 caracteres)`;
    counterEl.style.color = "var(--texto-secundario)";
    btn.disabled = true;
    btn.style.opacity = "0.4";
  }
}

function fillValidReflection() {
  goToScreen(22);
}

// Navegação via teclado
window.addEventListener("keydown", (e) => {
  if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA" || e.target.tagName === "SELECT") return;
  if (e.key === "ArrowRight") {
    if (currentScreenIndex < SCREENS.length - 1) goToScreen(currentScreenIndex + 1);
  } else if (e.key === "ArrowLeft") {
    if (currentScreenIndex > 0) goToScreen(currentScreenIndex - 1);
  }
});

document.getElementById("btnPrev").onclick = () => goToScreen(currentScreenIndex - 1);
document.getElementById("btnNext").onclick = () => goToScreen(currentScreenIndex + 1);

// Inicialização
renderScreen();
</script>
</body>
</html>
